import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DxgWTcNC.js";const u=JSON.parse('{"title":"Disassembly Tweaks, Hints, and Architecture Overrides","description":"","frontmatter":{},"headers":[],"relativePath":"part2/07-disasm-tweaks.md","filePath":"part2/07-disasm-tweaks.md","lastUpdated":null}'),i={name:"part2/07-disasm-tweaks.md"};function o(d,e,c,p,l,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="disassembly-tweaks-hints-and-architecture-overrides" tabindex="-1">Disassembly Tweaks, Hints, and Architecture Overrides <a class="header-anchor" href="#disassembly-tweaks-hints-and-architecture-overrides" aria-label="Permalink to &quot;Disassembly Tweaks, Hints, and Architecture Overrides&quot;">​</a></h1><p>The default disassembly is rarely the disassembly you want. This chapter covers the knobs that turn r2&#39;s output from &quot;technically correct&quot; into &quot;actually readable&quot;, plus the hints you use to override decisions r2 made wrongly.</p><h2 id="what-good-disassembly-looks-like" tabindex="-1">What &quot;good disassembly&quot; looks like <a class="header-anchor" href="#what-good-disassembly-looks-like" aria-label="Permalink to &quot;What &quot;good disassembly&quot; looks like&quot;">​</a></h2><p>Open a function with the default settings and you typically see:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08001234]&gt; pdf @ sym.main</span></span>
<span class="line"><span>            ; CALL XREF from sym.reset_handler @ 0x080001fa</span></span>
<span class="line"><span>┌ 64: int main (void);</span></span>
<span class="line"><span>│           0x08001234      80b5           push {r7, lr}</span></span>
<span class="line"><span>│           0x08001236      82b0           sub sp, 8</span></span>
<span class="line"><span>│           0x08001238      00af           add r7, sp, 0</span></span>
<span class="line"><span>│           0x0800123a      4ff48050       mov.w r0, 0x1000</span></span>
<span class="line"><span>│           0x0800123e      00f0c5fa       bl sym.HAL_Init</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>That is fine for a 5-line scratch read. For sustained work it is too busy: the bytes column is noise once you trust the disassembly, the addresses are too small to scan quickly, and there is no comment column.</p><p>A reasonable working configuration:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>e asm.bytes = false              # hide bytes column</span></span>
<span class="line"><span>e asm.cmt.right = true           # comments go to the right</span></span>
<span class="line"><span>e asm.cmt.col = 60               # column to start comments</span></span>
<span class="line"><span>e asm.lines.width = 14           # branch arrow width</span></span>
<span class="line"><span>e asm.flags.middle = 2           # show flags inline at function entry</span></span>
<span class="line"><span>e asm.var.summary = false        # show full var list at function top</span></span>
<span class="line"><span>e asm.fcnsig = true              # function signature header line</span></span>
<span class="line"><span>e asm.calls = true               # call comments inline</span></span>
<span class="line"><span>e asm.refptr = true              # resolve pointers shown as immediates</span></span>
<span class="line"><span>e asm.hint.cjmp = true           # mark conditional jumps</span></span>
<span class="line"><span>e asm.tabs = 0                   # spaces, not tabs</span></span>
<span class="line"><span>e asm.tabs.once = true           # one tab between mnemonic and operands</span></span>
<span class="line"><span>e asm.bb.middle = false          # don&#39;t show &quot;bb start&quot; in middle of fn</span></span></code></pre></div><p>After applying these (<code>eco</code> themes set most of them), the same function becomes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>┌ int main (void);</span></span>
<span class="line"><span>│ 0x08001234      push {r7, lr}</span></span>
<span class="line"><span>│ 0x08001236      sub sp, 8</span></span>
<span class="line"><span>│ 0x08001238      add r7, sp, 0</span></span>
<span class="line"><span>│ 0x0800123a      mov.w r0, 0x1000</span></span>
<span class="line"><span>│ 0x0800123e      bl HAL_Init                    ; sym.HAL_Init</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Quieter. Still all the information.</p><h2 id="architecture-overrides" tabindex="-1">Architecture overrides <a class="header-anchor" href="#architecture-overrides" aria-label="Permalink to &quot;Architecture overrides&quot;">​</a></h2><p>Sometimes r2 picked the wrong architecture for a region. Common cases:</p><ul><li>ARM Cortex-M binary with a small ARM-mode bootloader at the start and Thumb everywhere else.</li><li>MIPS binary with a few MIPS16 functions for size-constrained interrupt handlers.</li><li>RISC-V binary that uses compressed (RVC) instructions in some files and full RV32I in others.</li></ul><p>Override at the byte level with <code>ahb</code> (asm hint bits):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ahb 32 @ 0x08000000     # ARM mode for the bootloader</span></span>
<span class="line"><span>[0x...]&gt; ahb 16 @ 0x080001cd     # Thumb from here on</span></span>
<span class="line"><span>[0x...]&gt; ahb 16 @ 0x08001234..0x080013ff   # Thumb for a range</span></span></code></pre></div><p>For MIPS16 in a MIPS binary:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ahb 16 @ 0x80020000     # MIPS16 here</span></span>
<span class="line"><span>[0x...]&gt; ahb 32 @ 0x80020100     # back to standard MIPS</span></span></code></pre></div><p>For RISC-V compressed-only stretches:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; aha rvc @ 0x...         # treat as compressed</span></span></code></pre></div><p>After setting hints, run <code>aaa</code> again to re-decode and re-discover functions in the now-correct mode.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Hints persist in r2 projects, so once you have hinted the boundaries correctly, every future session loads them. This is one of the strongest reasons to use projects — re-discovering the ARM/Thumb boundary every session burns time you do not get back.</p></div><h2 id="per-instruction-tweaks" tabindex="-1">Per-instruction tweaks <a class="header-anchor" href="#per-instruction-tweaks" aria-label="Permalink to &quot;Per-instruction tweaks&quot;">​</a></h2><p>There are many <code>ah*</code> commands. The most useful in daily work:</p><table tabindex="0"><thead><tr><th>Command</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ahb N</code></td><td>bits at address (16/32/64)</td></tr><tr><td><code>aha mov</code></td><td>force the decoder to interpret as a different instruction</td></tr><tr><td><code>aho ret</code></td><td>set the instruction &quot;type&quot; (call, jmp, ret, …)</td></tr><tr><td><code>ahi h</code></td><td>display immediate as hex (also <code>b</code>, <code>o</code>, <code>d</code>)</td></tr><tr><td><code>ahi 8</code></td><td>display immediate as 8-bit char</td></tr><tr><td><code>ahi p</code></td><td>display immediate as pointer (resolve to flag)</td></tr><tr><td><code>ahS .text</code></td><td>set syntax variant</td></tr><tr><td><code>ahd &quot;label&quot;</code></td><td>display this address with a custom label</td></tr><tr><td><code>ahf</code></td><td>jump-to address override</td></tr><tr><td><code>ahc 0x...</code></td><td>call destination override</td></tr><tr><td><code>ahs N</code></td><td>byte size override</td></tr><tr><td><code>ahF N</code></td><td>offset format width</td></tr></tbody></table><p><code>ahd</code> is underrated. Use it to label MMIO accesses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ahd &quot;RCC-&gt;APB1ENR&quot; @ 0x4002101c</span></span></code></pre></div><p>Now every disassembly line that loads <code>0x4002101c</code> shows <code>RCC-&gt;APB1ENR</code> instead of the bare hex. Combined with <code>f</code> flags (named addresses), you get a peripheral map that reads like real C.</p><h2 id="marking-data-inside-code" tabindex="-1">Marking data inside code <a class="header-anchor" href="#marking-data-inside-code" aria-label="Permalink to &quot;Marking data inside code&quot;">​</a></h2><p>Embedded firmware is full of literal pools — short blocks of constants embedded in <code>.text</code> so that 32-bit immediates can be loaded with a PC-relative <code>LDR</code>. ARM Thumb especially. Without help, r2 will disassemble the literal pool as if it were code and produce garbage:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>0x080012a0      .word 0x40023800        ; r2 doesn&#39;t know this</span></span>
<span class="line"><span>0x080012a4      .word 0x00000001        ; ditto</span></span>
<span class="line"><span>0x080012a8      bl HAL_Init</span></span></code></pre></div><p>…unless you tell it. The <code>Cd</code> family marks bytes as data:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; Cd 4 @ 0x080012a0     # 4 bytes of data here</span></span>
<span class="line"><span>[0x...]&gt; Cd 4 @ 0x080012a4</span></span></code></pre></div><p><code>Cd 4</code> is &quot;decode this as a 4-byte word&quot;. Use <code>Cd 1</code>, <code>Cd 2</code>, <code>Cd 8</code> for other sizes. <code>Cs</code> marks a string. <code>Cf</code> marks a struct.</p><p>R2 should auto-detect literal pools after <code>aaa</code>, but it sometimes misses them, especially if the compiler scattered them in odd places. The &quot;random nonsensical instructions in the middle of an otherwise sensible function&quot; smell is almost always an unmarked literal pool.</p><p>Bulk-mark a range:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; Cd 4 @@= 0x080012a0 0x080012a4 0x080012a8</span></span>
<span class="line"><span>[0x...]&gt; CC- @@= 0x080012a0..0x080012c0    # remove all metadata in range</span></span></code></pre></div><h2 id="arm-specific-distinguishing-data-and-code-more-aggressively" tabindex="-1">ARM-specific: distinguishing data and code more aggressively <a class="header-anchor" href="#arm-specific-distinguishing-data-and-code-more-aggressively" aria-label="Permalink to &quot;ARM-specific: distinguishing data and code more aggressively&quot;">​</a></h2><p>ARM has a concept of &quot;mapping symbols&quot; (<code>$a</code>, <code>$t</code>, <code>$d</code>) that ELFs sometimes carry. R2 reads them. If your binary has them, ARM/Thumb boundaries are picked up automatically.</p><p>For binaries without mapping symbols, set:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; e anal.armthumb = true</span></span>
<span class="line"><span>[0x...]&gt; e asm.flags.real = true</span></span></code></pre></div><p>…then run <code>aaa</code>. R2 will use heuristics on call destinations (the low bit of a Thumb call is set; the low bit of an ARM call is clear) to infer the mode for each function.</p><h2 id="architecture-specific-syntax-variants" tabindex="-1">Architecture-specific syntax variants <a class="header-anchor" href="#architecture-specific-syntax-variants" aria-label="Permalink to &quot;Architecture-specific syntax variants&quot;">​</a></h2><p>Some architectures support multiple disassembly syntaxes. The big ones:</p><table tabindex="0"><thead><tr><th>Arch</th><th>Syntaxes available</th></tr></thead><tbody><tr><td>x86</td><td><code>intel</code> (default), <code>att</code>, <code>masm</code>, <code>nasm</code>, <code>jz</code></td></tr><tr><td>ARM</td><td><code>unified</code> (default), <code>divided</code></td></tr><tr><td>MIPS</td><td><code>o32</code>, <code>o32-mips32r6</code></td></tr><tr><td>8051</td><td><code>intel-syntax</code>, <code>nec-syntax</code></td></tr></tbody></table><p>Switch with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; e asm.syntax = att      # x86 in AT&amp;T syntax</span></span>
<span class="line"><span>[0x...]&gt; e asm.syntax = unified  # ARM unified</span></span></code></pre></div><p>Set per-function with <code>ahS</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ahS att @ sym.foo</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Mixing syntaxes within one binary makes the disassembly hard to read even for experts. Pick one and stick to it. The default is almost always the right choice; the only time to switch is when you are copying disassembly into a tool that expects the other syntax (e.g., GAS source).</p></div><h2 id="sanity-checking-after-a-tweak" tabindex="-1">Sanity-checking after a tweak <a class="header-anchor" href="#sanity-checking-after-a-tweak" aria-label="Permalink to &quot;Sanity-checking after a tweak&quot;">​</a></h2><p>Every time you set a hint or override a tweak, do a quick read to make sure it did what you wanted:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ah                      # list all active hints</span></span>
<span class="line"><span>[0x...]&gt; ah @ 0x08001234         # hints at this address</span></span>
<span class="line"><span>[0x...]&gt; ah- @ 0x08001234        # delete a hint</span></span>
<span class="line"><span>[0x...]&gt; ah-*                    # delete all hints (careful)</span></span></code></pre></div><p><code>ah*</code> (with <code>*</code> suffix) outputs the hints as r2 commands you can save and replay — useful if you want to share your hint set with a colleague or commit it to a script.</p><p>Once your disassembly reads cleanly, the rest of the static-analysis toolkit (functions, types, decompilation, signatures) becomes much more productive — those tools assume the disassembly underneath is right.</p>`,55)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
